test('5.1 — score (ON TARGET) is a valid percentage during gameplay', async ({ page }) => {
  // Note: with mocked x=0,y=0 accelerometer the cursor stays on-target immediately,
  // so score climbs to 100% quickly. We verify it's a valid numeric % value.
  const game = new GamePage(page, GAME_PATH, ACCENT)
  await game.goto({ sensors: { motion: true } })
  await game.start()
  await game.waitForPlaying()

  const scoreText = await game.scoreEl.textContent().catch(() => '0%')
  const scoreNum = parseInt(scoreText?.replace('%', '').trim() ?? '0', 10)
  // Score must be a valid integer percentage 0-100
  expect(scoreNum).toBeGreaterThanOrEqual(0)
  expect(scoreNum).toBeLessThanOrEqual(100)
})

test('5.2 — game ends when timer reaches 0', async ({ page }) => {
  await page.addInitScript(() => {
    const orig = window.setInterval.bind(window)
    ;(window as any).setInterval = (fn: () => void, ms: number, ...args: unknown[]) => {
      if (ms === 1000) return orig(fn, 100, ...args)  // 10x faster
      return orig(fn, ms, ...args)
    }
  })

  const game = new GamePage(page, GAME_PATH, ACCENT)
  await game.goto({ sensors: { motion: true } })
  await game.start()

  await page.waitForSelector('button:has-text("Play Again")', {
    timeout: Math.ceil(GAME_DURATION_MS / 10) + 8000
  })
  await expect(game.playAgainButton).toBeVisible()
})

test('5.3 — play-again resets score to valid range', async ({ page }) => {
  await page.addInitScript(() => {
    const orig = window.setInterval.bind(window)
    ;(window as any).setInterval = (fn: () => void, ms: number, ...args: unknown[]) => {
      if (ms === 1000) return orig(fn, 100, ...args)
      return orig(fn, ms, ...args)
    }
  })

  const game = new GamePage(page, GAME_PATH, ACCENT)
  await game.goto({ sensors: { motion: true } })
  await game.start()
  await game.waitForEnd(GAME_DURATION_MS / 10 + 8000)
  // play-again returns to start screen — must start again
  await game.playAgain()
  // savePlayerSession (called on first handleStart) overwrites mg_user without preserving
  // consented:true — re-set it so the consent screen doesn't block the second start.
  await page.evaluate(() => {
    try {
      const u = JSON.parse(localStorage.getItem('mg_user') ?? '{}')
      u.consented = true
      localStorage.setItem('mg_user', JSON.stringify(u))
    } catch { /* ignore */ }
  })
  await game.start()
  // Bypass 4s waitForPlaying — poll for score element immediately
  await page.waitForSelector('[data-testid="score"]', { timeout: 10000 })
  await page.waitForTimeout(200)  // 200 ms stabilization

  const scoreText = await game.scoreEl.textContent().catch(() => '0%')
  const scoreNum = parseInt(scoreText?.replace('%', '').trim() ?? '0', 10)
  expect(scoreNum).toBeGreaterThanOrEqual(0)
  expect(scoreNum).toBeLessThanOrEqual(100)
})

test('5.4 — timer resets correctly after play-again', async ({ page }) => {
  await page.addInitScript(() => {
    const orig = window.setInterval.bind(window)
    ;(window as any).setInterval = (fn: () => void, ms: number, ...args: unknown[]) => {
      if (ms === 1000) return orig(fn, 100, ...args)
      return orig(fn, ms, ...args)
    }
  })

  const game = new GamePage(page, GAME_PATH, ACCENT)
  await game.goto({ sensors: { motion: true } })
  await game.start()
  await game.waitForEnd(GAME_DURATION_MS / 10 + 8000)
  // play-again returns to start screen — must start again
  await game.playAgain()
  // Re-assert consent:true — savePlayerSession on first play clears it
  await page.evaluate(() => {
    try {
      const u = JSON.parse(localStorage.getItem('mg_user') ?? '{}')
      u.consented = true
      localStorage.setItem('mg_user', JSON.stringify(u))
    } catch { /* ignore */ }
  })
  await game.start()
  // Bypass the 4s waitForPlaying overhead (which exhausts the 10× timer).
  // Poll for timer element immediately after playing phase starts.
  await page.waitForSelector('[data-testid="timer"]', { timeout: 10000 })
  await page.waitForTimeout(150)  // 150 ms real = 1.5 game-s at 10× — timer is still high

  const timerText = await game.timerEl.textContent().catch(() => '0')
  const timer = parseInt(timerText ?? '0')
  // Timer should have reset to DURATION and be actively counting down (not stuck at 0).
  expect(timer, `Timer should be > 0 after reset, got ${timer}`).toBeGreaterThan(0)
})

