test('9.4 — end screen passes axe-core scan', async ({ page }) => {
  await page.addInitScript(() => {
    const orig = window.setInterval.bind(window)
    ;(window as any).setInterval = (fn: () => void, ms: number, ...args: unknown[]) => {
      if (ms === 1000) return orig(fn, 100, ...args)
      return orig(fn, ms, ...args)
    }
  })

  const game = new GamePage(page, GAME_PATH, ACCENT)
  await game.goto()
  await game.start()
  await game.waitForEnd(GAME_DURATION_MS / 10 + 8000)

  // Wait for framer-motion entry animations to fully complete (Play Again button has
  // delay:0.44s + spring animation). Axe at partial opacity gives wrong effective colors.
  await page.waitForTimeout(1500)
  // Remove confetti canvas overlays — they last 4s and can corrupt color sampling.
  await page.evaluate(() => document.querySelectorAll('canvas').forEach(c => c.remove()))
  await page.waitForTimeout(200)

  const results = await new AxeBuilder({ page })
    .withTags(['wcag2a', 'wcag2aa'])
    .exclude('canvas')
    .analyze()

  const critical = results.violations.filter(v => v.impact === 'critical' || v.impact === 'serious')
  expect(critical, `End screen violations: ${critical.map(v => v.id).join(', ')}`).toHaveLength(0)
})

// ─── 10. MOTION GAME SPECIFIC ─────────────────────────────────────────────────

test('10.1 — touch fallback activates when motion denied', async ({ page }) => {
  await page.addInitScript(() => {
    ;(window as any).DeviceMotionEvent = class extends Event {
      static requestPermission = async () => 'denied'
      accelerationIncludingGravity = { x: 0, y: 0, z: 9.8 }
    }
  })
  const game = new GamePage(page, GAME_PATH, ACCENT)
  await game.goto()
  await game.start()
  await game.waitForPlaying()
  // Game should still render canvas (touch fallback active)
  await expect(game.canvas).toBeVisible({ timeout: 3000 })
})

test('10.2 — haptics=off URL param disables vibration', async ({ page }) => {
  // Inject vibrate spy before load
  await page.addInitScript(() => {
    ;(window as any).__vibrateLog = []
    navigator.vibrate = (pattern: number | number[]) => {
      ;(window as any).__vibrateLog.push(pattern)
      return true
    }
  })

  // Navigate WITH haptics=off
  const game = new GamePage(page, GAME_PATH + '?haptics=off', ACCENT)
  await game.goto({ sensors: { motion: true } })
  await game.start()
  await game.waitForPlaying()
  await page.waitForTimeout(3000)

  // No vibration should have fired during the game
  const log = await page.evaluate(() => (window as any).__vibrateLog)
  expect(log.length, 'Vibrations fired despite haptics=off').toBe(0)
})

